def is_valid_ipv4(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # must be non‑empty and all digits
        if not part or not part.isdigit():
            return False
        # no leading zeros unless the number is exactly "0"
        if part[0] == '0' and len(part) > 1:
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True

